"""CIRCUS random-subset stability analysis (node-informed variant)."""

import re
import random
from typing import Dict, Set, Tuple, List

from config import MVPConfig, MVP_CONFIG


def random_subset_circuits(
    all_edges: Set[str],
    n_circuits: int = 100,
    subset_fraction: float = 0.1,
    seed: int = 42,
) -> List[Set[str]]:
    rng = random.Random(seed)
    edge_list = sorted(all_edges)
    k = max(1, int(len(edge_list) * subset_fraction))
    return [set(rng.sample(edge_list, k)) for _ in range(n_circuits)]


def _extract_nodes_from_edges(edges: Set[str]) -> Set[str]:
    nodes = set()
    for e in edges:
        parts = e.split("->")
        if len(parts) != 2:
            continue
        src = parts[0].strip()
        dst = parts[1].strip()
        nodes.add(src)
        dst_base = re.sub(r"\.[qkv]$", "", dst)
        if dst_base not in ("logits", "input"):
            nodes.add(dst_base)
    nodes.discard("input")
    return nodes


def compute_circus_scores_node(
    subsets: List[Set[str]],
    cpr_values: List[float],
) -> Tuple[Dict[str, float], Dict[str, float]]:
    """Node-informed CIRCUS: compute per-node importance, map to edges.

    Returns (edge_scores, node_scores).
    """
    subset_nodes = [_extract_nodes_from_edges(s) for s in subsets]
    all_nodes: Set[str] = set()
    for ns in subset_nodes:
        all_nodes |= ns

    node_scores: Dict[str, float] = {}
    for node in all_nodes:
        cprs_with = [cpr_values[i] for i, ns in enumerate(subset_nodes) if node in ns]
        cprs_without = [cpr_values[i] for i, ns in enumerate(subset_nodes) if node not in ns]
        mean_with = sum(cprs_with) / len(cprs_with) if cprs_with else 0.0
        mean_without = sum(cprs_without) / len(cprs_without) if cprs_without else 0.0
        node_scores[node] = mean_with - mean_without

    all_edges: Set[str] = set()
    for s in subsets:
        all_edges |= s

    edge_scores: Dict[str, float] = {}
    for edge in all_edges:
        parts = edge.split("->")
        src = parts[0].strip()
        dst = parts[1].strip()
        dst_base = re.sub(r"\.[qkv]$", "", dst)

        src_score = node_scores.get(src, 0.0)
        if dst_base in ("logits", "input"):
            edge_scores[edge] = src_score
        else:
            dst_score = node_scores.get(dst_base, 0.0)
            edge_scores[edge] = max(src_score, dst_score)

    return edge_scores, node_scores


def compute_circus_scores(
    subsets: List[Set[str]],
    faithful: List[bool],
) -> Dict[str, float]:
    """Binary CIRCUS score = P(faithful | edge in subset)."""
    all_edges: Set[str] = set()
    for s in subsets:
        all_edges |= s
    scores = {}
    for edge in all_edges:
        containing = [i for i, s in enumerate(subsets) if edge in s]
        if not containing:
            scores[edge] = 0.0
            continue
        scores[edge] = sum(1 for i in containing if faithful[i]) / len(containing)
    return scores


def compute_circus_scores_weighted(
    subsets: List[Set[str]],
    cpr_values: List[float],
) -> Dict[str, float]:
    """Weighted CIRCUS: score = mean(CPR_with) - mean(CPR_without)."""
    all_edges: Set[str] = set()
    for s in subsets:
        all_edges |= s
    scores = {}
    for edge in all_edges:
        cprs_with = [cpr_values[i] for i, s in enumerate(subsets) if edge in s]
        cprs_without = [cpr_values[i] for i, s in enumerate(subsets) if edge not in s]
        mean_with = sum(cprs_with) / len(cprs_with) if cprs_with else 0.0
        mean_without = sum(cprs_without) / len(cprs_without) if cprs_without else 0.0
        scores[edge] = mean_with - mean_without
    return scores


def get_circus_tiers(
    stability_scores: Dict[str, float],
    core_threshold: float = 1.0,
    contingent_threshold: float = 0.5,
) -> Dict[str, str]:
    tiers = {}
    for edge, score in stability_scores.items():
        if score >= core_threshold:
            tiers[edge] = "core"
        elif score >= contingent_threshold:
            tiers[edge] = "contingent"
        else:
            tiers[edge] = "noise"
    return tiers


def get_tier_sets(tiers: Dict[str, str]) -> Dict[str, Set[str]]:
    result: Dict[str, Set[str]] = {"core": set(), "contingent": set(), "noise": set()}
    for edge, tier in tiers.items():
        result[tier].add(edge)
    return result


def run_circus(
    edge_scores: Dict[str, float],
    config: MVPConfig = MVP_CONFIG,
) -> Tuple[Dict[str, float], Dict[str, str]]:
    """Legacy score-based interface."""
    stability = _config_bag_legacy(edge_scores, B=config.circus_B)
    tiers = get_circus_tiers(
        stability,
        core_threshold=config.circus_core_threshold,
        contingent_threshold=config.circus_contingent_threshold,
    )
    tier_counts = {t: sum(1 for v in tiers.values() if v == t) for t in ["core", "contingent", "noise"]}
    print(f"CIRCUS tiers: {tier_counts}")
    return stability, tiers


def _config_bag_legacy(edge_scores: Dict[str, float], B: int = 10) -> Dict[str, float]:
    import numpy as np
    if not edge_scores:
        return {}
    edges = list(edge_scores.keys())
    scores = np.array([edge_scores[e] for e in edges])
    abs_scores = np.abs(scores)
    node_max: Dict[str, float] = {}
    for e, s in edge_scores.items():
        src = e.split("->")[0]
        node_max[src] = max(node_max.get(src, float("-inf")), abs(s))
    node_scores = np.array([node_max[e.split("->")[0]] for e in edges])
    t = np.linspace(0, 1, B)
    node_pcts = 10 + 80 * t
    edge_pcts = 10 + 80 * (1 - t)
    node_threshs = np.percentile(node_scores, node_pcts)
    edge_threshs = np.percentile(abs_scores, edge_pcts)
    stability = np.zeros(len(edges))
    for nt, et in zip(node_threshs, edge_threshs):
        included = (node_scores >= nt) & (abs_scores >= et)
        stability += included.astype(float)
    stability /= B
    return {edge: float(stab) for edge, stab in zip(edges, stability)}
