"""CIRCUS-core x CSS cross-tabulation."""

from typing import Dict, Set
from dataclasses import dataclass


@dataclass
class CrossTable:
    stable_core: Set[str]
    method_specific: Set[str]
    cross_unstable: Set[str]
    noise: Set[str]

    @property
    def total(self) -> int:
        return len(self.stable_core) + len(self.method_specific) + len(self.cross_unstable) + len(self.noise)

    @property
    def core_total(self) -> int:
        return len(self.stable_core) + len(self.method_specific)

    @property
    def core_off_diagonal_pct(self) -> float:
        if self.core_total == 0:
            return 0.0
        return len(self.method_specific) / self.core_total

    def summary(self) -> Dict[str, object]:
        return {
            "stable_core": len(self.stable_core),
            "method_specific": len(self.method_specific),
            "cross_unstable": len(self.cross_unstable),
            "noise": len(self.noise),
            "total": self.total,
            "core_total": self.core_total,
            "core_off_diagonal_pct": round(self.core_off_diagonal_pct, 4),
        }


def cross_tabulate(circus_tiers: Dict[str, str], css_scores: Dict[str, float], css_threshold: float = 0.67) -> CrossTable:
    all_edges = set(circus_tiers.keys()) | set(css_scores.keys())
    stable_core = set()
    method_specific = set()
    cross_unstable = set()
    noise = set()

    for edge in all_edges:
        is_circus_core = circus_tiers.get(edge) == "core"
        css_high = css_scores.get(edge, 0.0) >= css_threshold - 1e-2

        if is_circus_core and css_high:
            stable_core.add(edge)
        elif is_circus_core and not css_high:
            method_specific.add(edge)
        elif not is_circus_core and css_high:
            cross_unstable.add(edge)
        else:
            noise.add(edge)

    return CrossTable(stable_core=stable_core, method_specific=method_specific, cross_unstable=cross_unstable, noise=noise)


def compute_off_diagonal(table: CrossTable) -> float:
    return table.core_off_diagonal_pct


def print_cross_table(table: CrossTable) -> None:
    s = table.summary()
    print(f"\n{'='*50}")
    print(f"CIRCUS-core x CSS Cross-Tabulation")
    print(f"{'='*50}")
    print(f"                  | CSS >= thr  | CSS < thr   |")
    print(f"  CIRCUS-core     | {s['stable_core']:>5} edges | {s['method_specific']:>5} edges |")
    print(f"  CIRCUS-other    | {s['cross_unstable']:>5} edges | {s['noise']:>5} edges |")
    print(f"{'='*50}")
    print(f"  Total edges: {s['total']}  |  CIRCUS-core: {s['core_total']}")
    print(f"  Core off-diagonal %: {s['core_off_diagonal_pct']*100:.1f}% (method_specific / core_total)")
    print(f"{'='*50}\n")


from itertools import combinations
from typing import List, Tuple


def pairwise_jaccard(method_circuits: Dict[str, Set[str]]) -> List[Tuple[str, str, float, int, int]]:
    results = []
    methods = sorted(method_circuits.keys())
    for m1, m2 in combinations(methods, 2):
        a, b = method_circuits[m1], method_circuits[m2]
        union = a | b
        inter = a & b
        jac = len(inter) / len(union) if union else 0.0
        results.append((m1, m2, jac, len(inter), len(union)))
    return results


def three_way_jaccard(method_circuits: Dict[str, Set[str]]) -> Tuple[float, int, int]:
    sets = list(method_circuits.values())
    inter = sets[0]
    union = sets[0]
    for s in sets[1:]:
        inter = inter & s
        union = union | s
    jac = len(inter) / len(union) if union else 0.0
    return jac, len(inter), len(union)


def print_pairwise_jaccard(pw: List[Tuple[str, str, float, int, int]], tw: Tuple[float, int, int]) -> None:
